-- READ-ONLY preflight for the LIVE project (generated by make-dryruns.py). One SELECT; it changes nothing.
-- Run it before anything else on live and send me the result.
--   * Any row whose kind starts with 'CONFLICT' means teams-final.sql would replace or clash with
--     something that already exists there (for example a handle_new_user() from a Supabase template),
--     and teams-rollback.sql would then drop it. Stop and tell me.
--   * The other rows are an inventory: extensions, event triggers, public functions, triggers on
--     auth.users / tasks, tables and policies in public, and the columns of tasks.

  select 'CONFLICT: function already exists' as kind, proname::text as name from pg_proc where pronamespace = 'public'::regnamespace and proname = any (array['accept_task', 'assign_task', 'cancel_handoff', 'complete_task', 'create_project', 'decline_task', 'ensure_profile', 'handle_new_user', 'is_member_of', 'is_project_member', 'is_project_owner', 'join_project', 'leave_project', 'new_join_code', 'provision_user', 'reopen_task', 'request_handoff', 'require_user', 'respond_handoff', 'shares_project', 'take_task', 'task_for_update', 'tasks_before_insert', 'tasks_before_update']::text[])
  union all
  select 'CONFLICT: table already exists', relname::text from pg_class where relnamespace = 'public'::regnamespace and relname = any (array['profiles', 'project_members', 'projects']::text[])
  union all
  select 'CONFLICT: column already on tasks', column_name::text from information_schema.columns where table_schema = 'public' and table_name = 'tasks' and column_name = any (array['project_id', 'assignee_id', 'state', 'accepted_by', 'accepted_at', 'declined_by', 'declined_at', 'handoff_to', 'handoff_requested_at', 'completed_at']::text[])
  union all
  select 'CONFLICT: trigger name in use', tgname::text || ' on ' || tgrelid::regclass::text from pg_trigger where not tgisinternal and tgname = any (array['on_auth_user_created', 'tasks_before_insert', 'tasks_before_update']::text[])
  union all
  select 'CONFLICT: index name in use', indexname::text from pg_indexes where schemaname = 'public' and indexname = any (array['project_members_user_id_idx', 'projects_one_personal_per_user', 'tasks_assignee_id_idx', 'tasks_project_id_created_at_idx']::text[])
  union all
  select 'CONFLICT: policy name in use', policyname::text || ' on ' || tablename::text from pg_policies where schemaname = 'public' and policyname = any (array['Members: members read', 'Profiles: edit own', 'Profiles: read own and teammates', 'Projects: members read', 'Projects: owners rename', 'Tasks: members read project tasks', 'Tasks: only inside your projects (delete)', 'Tasks: only inside your projects (insert)', 'Tasks: only inside your projects (select)', 'Tasks: only inside your projects (update)', 'Tasks: project owners delete']::text[])
  union all
  select 'CONFLICT: constraint name in use', conname::text from pg_constraint where conname = 'tasks_state_check'
  union all
  select 'extension', extname || ' ' || extversion || ' (schema ' || extnamespace::regnamespace::text || ')' from pg_extension
  union all
  select 'event trigger', evtname || ' -> ' || evtfoid::regproc::text || ' on ' || evtevent
         || coalesce(' [' || array_to_string(evttags, ', ') || ']', '') || case evtenabled when 'D' then ' (disabled)' else '' end
    from pg_event_trigger
  union all
  select 'function in public', p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')'
         || case when p.proname = any (array['rls_auto_enable']::text[]) then '  [known platform function]' else '' end
    from pg_proc p where p.pronamespace = 'public'::regnamespace
  union all
  select 'trigger', tgname || ' on ' || tgrelid::regclass::text from pg_trigger
   where not tgisinternal and tgrelid in ('auth.users'::regclass, 'public.tasks'::regclass)
  union all
  select 'table in public', relname || case when relrowsecurity then ' (RLS on)' else ' (RLS OFF)' end
    from pg_class where relnamespace = 'public'::regnamespace and relkind in ('r', 'p')
  union all
  select 'policy', policyname || ' on ' || tablename from pg_policies where schemaname = 'public'
  union all
  select 'tasks column', column_name || ' ' || data_type from information_schema.columns
   where table_schema = 'public' and table_name = 'tasks'
  union all
  select 'counts', 'tasks: ' || (select count(*) from public.tasks) || ', users: ' || (select count(*) from auth.users)
  order by 1, 2;
